+// Shipping in cents by total weight in grams: a base fee plus a fee per started kilogram.
+export const BASE_CENTS = 499;
+export const PER_KG_CENTS = 150;
+
+export function shippingCents(grams) {
+  if (!Number.isFinite(grams) || grams < 0) throw new RangeError(`grams must be non-negative: ${grams}`);
+  if (grams === 0) return 0;
+  return BASE_CENTS + PER_KG_CENTS * Math.ceil(grams / 1000);
+}

